"""Credential-free public GitHub reads and bounded immutable source archives.

Repository content is untrusted data. This module never clones, extracts onto the
host filesystem, executes files, follows redirects, or uses ambient credentials.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from functools import wraps
import asyncio
import gzip
import io
import re
import tarfile
from urllib.parse import quote

import httpx

from agentforge.integrations.tls import outbound_tls

MAX_COMPRESSED_BYTES = 10_000_000
MAX_ARCHIVE_BYTES = 30_000_000
MAX_FILE_BYTES = 1_000_000
MAX_FILES = 2_000
_REPO = re.compile(r"[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})/[A-Za-z0-9_.-]{1,100}\Z")
_SHA = re.compile(r"[0-9a-f]{40}\Z")


class GitHubError(ValueError):
    """A stable public error code with no upstream response content."""


@dataclass(frozen=True)
class ResolvedRepository:
    repo_id: str
    commit_sha: str
    default_branch: str


@dataclass(frozen=True)
class RepositorySnapshot:
    repo_id: str
    commit_sha: str
    files: dict[str, bytes]
    # Unix mode per path (0o755 executable, 0o644 otherwise) when the source knows it; empty means 0o644 for all.
    modes: dict[str, int] = field(default_factory=dict)
    # (path, reason) of every file left out of `files`; see `skip_reason`. The rest of the repository is still complete.
    skipped: tuple[tuple[str, str], ...] = ()


def validate_repo_id(repo_id: str) -> str:
    if not isinstance(repo_id, str) or not _REPO.fullmatch(repo_id) or repo_id.split("/")[1] in {".", ".."}:
        raise GitHubError("github_invalid_repository")
    return repo_id


def _safe_path(name: str) -> tuple[str, ...]:
    parts = name.split("/")
    if (not name or len(name) > 1000 or name.startswith("/") or "\\" in name or
            any(part in {"", ".", ".."} for part in parts) or
            any(ord(char) < 32 or ord(char) == 127 for char in name) or ":" in name):
        raise GitHubError("github_unsafe_archive_path")
    return tuple(parts)


def _secret_path(parts: tuple[str, ...]) -> bool:
    for part in parts:
        value = part.lower()
        if value == ".git" or value in {".netrc", ".npmrc", ".pypirc", "credentials", "id_rsa", "id_ed25519"}:
            return True
        if value == ".env" or (value.startswith(".env.") and value not in {".env.example", ".env.sample", ".env.template"}):
            return True
        if value.endswith((".pem", ".key", ".p12", ".pfx", ".keystore")):
            return True
    return False


def skip_reason(path: str) -> str | None:
    """Why one repository file is left out of a snapshot, or None when it is kept.

    A file that cannot be loaded (secrets, an unsafe name, ...) is skipped; it never fails the rest of the repository.
    """
    try:
        parts = _safe_path(path)
    except GitHubError:
        return "unsafe_name"
    if _secret_path(parts):
        return "sensitive"
    from agentforge.sandbox.workspace import validate_path
    try:
        validate_path(path)
    except ValueError as error:
        return "sensitive" if "sensitive" in str(error) else "unsafe_name"
    return None


def checked_workspace(files: dict[str, bytes]) -> dict[str, bytes]:
    """The files as a validated workspace, or a GitHubError saying which limit the repository is over."""
    from agentforge.sandbox.workspace import validate_workspace
    try:
        return validate_workspace(files)
    except ValueError as error:
        limit = {"workspace_file_limit": "github_archive_file_count_limit",
                 "workspace_byte_limit": "github_archive_decompressed_limit"}
        raise GitHubError(limit.get(str(error), "github_archive_workspace_invalid")) from None


def is_transient(error: GitHubError) -> bool:
    """True when asking again later may work (GitHub busy or unreachable); False when the same request will always fail."""
    return str(error) in {"github_rate_limited", "github_read_unavailable", "github_unavailable"}


def read_archive(compressed: bytes) -> tuple[dict[str, bytes], list[tuple[str, str]]]:
    """The regular files of a GitHub source archive and the (path, reason) of each one left out.

    Left out, not fatal: secrets, links, special files, unsafe names, files over MAX_FILE_BYTES and names that differ only by
    letter case. Fatal: an archive that is malformed, empty, or over a size or count limit as a whole.
    """
    if len(compressed) > MAX_COMPRESSED_BYTES:
        raise GitHubError("github_archive_compressed_limit")
    try:
        with gzip.GzipFile(fileobj=io.BytesIO(compressed)) as stream:
            archive = stream.read(MAX_ARCHIVE_BYTES + 1)
        if len(archive) > MAX_ARCHIVE_BYTES:
            raise GitHubError("github_archive_decompressed_limit")
        files: dict[str, bytes] = {}
        skipped: list[tuple[str, str]] = []
        root: str | None = None
        seen: set[str] = set()
        folded: set[str] = set()
        total_bytes = 0
        with tarfile.open(fileobj=io.BytesIO(archive), mode="r:") as tar:
            for count, member in enumerate(tar, start=1):
                if count > MAX_FILES:
                    raise GitHubError("github_archive_file_count_limit")
                name = member.name.rstrip("/") if member.isdir() else member.name
                parts = name.split("/")
                if root is None:
                    root = parts[0]
                    if _safe_path(root) != (root,):
                        raise GitHubError("github_archive_root_invalid")
                if parts[0] != root or (len(parts) == 1 and not member.isdir()):
                    raise GitHubError("github_archive_root_invalid")
                if member.isdir():
                    continue  # a folder carries nothing; one whose files are all skipped is simply never created
                if name in seen:
                    raise GitHubError("github_archive_duplicate_path")
                seen.add(name)
                path = "/".join(parts[1:])
                if member.issym() or member.islnk():
                    reason = "symlink"
                elif not member.isfile():
                    reason = "special"
                else:
                    reason = skip_reason(path)
                    if reason is None and (member.size < 0 or member.size > MAX_FILE_BYTES):
                        reason = "too_large"
                    elif reason is None and path.casefold() in folded:
                        reason = "case_clash"
                if reason:
                    skipped.append((path, reason))
                    continue
                total_bytes += member.size
                if total_bytes > MAX_ARCHIVE_BYTES:
                    raise GitHubError("github_archive_decompressed_limit")
                extracted = tar.extractfile(member)
                if extracted is None:
                    raise GitHubError("github_archive_invalid")
                data = extracted.read(MAX_FILE_BYTES + 1)
                if len(data) != member.size:
                    raise GitHubError("github_archive_invalid")
                files[path] = data
                folded.add(path.casefold())
        if not files:
            raise GitHubError("github_repository_empty")
        # Reject directory/file collisions even if the tar's entry order differs.
        for path in files:
            parts = path.split("/")
            if any("/".join(parts[:index]) in files for index in range(1, len(parts))):
                raise GitHubError("github_archive_path_collision")
        return checked_workspace(files), skipped
    except GitHubError:
        raise
    except (tarfile.TarError, OSError, EOFError, ValueError):
        raise GitHubError("github_archive_invalid") from None


def unpack_archive(compressed: bytes) -> dict[str, bytes]:
    return read_archive(compressed)[0]


def _deadline(seconds: float):
    def decorate(function):
        @wraps(function)
        async def bounded(*args, **kwargs):
            try:
                async with asyncio.timeout(seconds):
                    return await function(*args, **kwargs)
            except TimeoutError:
                raise GitHubError("github_read_unavailable") from None
        return bounded
    return decorate


class GitHubClient:
    def __init__(self, *, transport: httpx.AsyncBaseTransport | None = None):
        self.transport = transport

    def _client(self) -> httpx.AsyncClient:
        return httpx.AsyncClient(timeout=httpx.Timeout(20, connect=5), follow_redirects=False,
            trust_env=False, verify=outbound_tls(), transport=self.transport, headers={"Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "AgentForge-public-source"})

    @staticmethod
    async def _read(client: httpx.AsyncClient, url: str, maximum: int) -> bytes:
        try:
            async with client.stream("GET", url) as response:
                if response.status_code == 404:
                    raise GitHubError("github_public_repository_or_ref_not_found")
                if response.status_code in {403, 429}:
                    raise GitHubError("github_rate_limited")
                if response.status_code != 200:
                    raise GitHubError("github_read_unavailable")
                length = response.headers.get("content-length")
                if length and (not length.isdigit() or int(length) > maximum):
                    raise GitHubError("github_response_size_limit")
                data = bytearray()
                async for chunk in response.aiter_bytes():
                    data.extend(chunk)
                    if len(data) > maximum:
                        raise GitHubError("github_response_size_limit")
                return bytes(data)
        except httpx.HTTPError:
            raise GitHubError("github_read_unavailable") from None

    async def _json(self, client: httpx.AsyncClient, path: str) -> dict:
        import json
        try:
            value = json.loads(await self._read(client, f"https://api.github.com{path}", 500_000))
            if not isinstance(value, dict):
                raise ValueError()
            return value
        except (ValueError, UnicodeDecodeError) as error:
            if isinstance(error, GitHubError):
                raise
            raise GitHubError("github_response_invalid") from None

    @_deadline(45)
    async def resolve(self, repo_id: str, ref: str = "HEAD", *, issue_number: int | None = None) -> ResolvedRepository:
        repo_id = validate_repo_id(repo_id)
        if not ref or len(ref) > 255 or any(ord(char) < 32 for char in ref):
            raise GitHubError("github_invalid_ref")
        async with self._client() as client:
            repository = await self._json(client, f"/repos/{repo_id}")
            if repository.get("private") is not False or repository.get("visibility") not in {None, "public"}:
                raise GitHubError("github_public_repository_required")
            canonical = validate_repo_id(repository.get("full_name", ""))
            # Renames must be explicitly selected, rather than following redirects.
            if canonical.lower() != repo_id.lower():
                raise GitHubError("github_repository_identity_changed")
            commit = await self._json(client, f"/repos/{canonical}/commits/{quote(ref, safe='')}")
            sha = commit.get("sha", "")
            if not isinstance(sha, str) or not _SHA.fullmatch(sha):
                raise GitHubError("github_response_invalid")
            if issue_number is not None:
                issue = await self._json(client, f"/repos/{canonical}/issues/{issue_number}")
                if issue.get("number") != issue_number or "pull_request" in issue:
                    raise GitHubError("github_issue_not_found")
            branch = repository.get("default_branch", "")
            return ResolvedRepository(canonical, sha, branch if isinstance(branch, str) else "")

    @_deadline(45)
    async def get_issue(self, repo_id: str, issue_number: int) -> dict:
        repo_id = validate_repo_id(repo_id)
        if isinstance(issue_number, bool) or not isinstance(issue_number, int) or not 1 <= issue_number <= 2_147_483_647:
            raise GitHubError("github_issue_not_found")
        async with self._client() as client:
            repository = await self._json(client, f"/repos/{repo_id}")
            if repository.get("private") is not False or repository.get("visibility") not in {None, "public"}:
                raise GitHubError("github_public_repository_required")
            issue = await self._json(client, f"/repos/{repo_id}/issues/{issue_number}")
            if issue.get("number") != issue_number or "pull_request" in issue:
                raise GitHubError("github_issue_not_found")
            title, body, state = issue.get("title", ""), issue.get("body") or "", issue.get("state", "")
            if not all(isinstance(value, str) for value in (title, body, state)) or len(body.encode()) > 100_000 or len(title) > 1000:
                raise GitHubError("github_issue_size_limit")
            return {"number": issue_number, "title": title, "body": body, "state": state,
                    "url": f"https://github.com/{repo_id}/issues/{issue_number}"}

    @_deadline(90)
    async def snapshot(self, repo_id: str, ref: str) -> RepositorySnapshot:
        if not _SHA.fullmatch(ref):
            raise GitHubError("github_immutable_commit_required")
        resolved = await self.resolve(repo_id, ref)
        if resolved.commit_sha != ref:
            raise GitHubError("github_commit_mismatch")
        async with self._client() as client:
            archive = await self._read(client,
                f"https://codeload.github.com/{resolved.repo_id}/tar.gz/{resolved.commit_sha}", MAX_COMPRESSED_BYTES)
        files, skipped = read_archive(archive)
        return RepositorySnapshot(resolved.repo_id, resolved.commit_sha, files, skipped=tuple(skipped))

"""Byte-only workspaces: never check out, import, or execute repository code locally."""

import difflib
import gzip
import hashlib
import io
import json
import tarfile
import unicodedata
from collections.abc import Mapping
from pathlib import PurePosixPath

MAX_FILES = 2000
MAX_FILE_BYTES = 1_000_000
MAX_WORKSPACE_BYTES = 10_000_000
MAX_ARCHIVE_BYTES = 12_000_000


def validate_path(path: str) -> str:
    if not isinstance(path, str) or not path or len(path.encode()) > 1024:
        raise ValueError("invalid_workspace_path")
    parts = path.split("/")
    if (path.startswith("/") or "\\" in path or any(p in ("", ".", "..") for p in parts)
            or any(unicodedata.category(c).startswith("C") for c in path)
            or ":" in path or unicodedata.normalize("NFC", path) != path):
        raise ValueError("invalid_workspace_path")
    lowered = [p.casefold() for p in parts]
    if any(p in (".git", ".ssh", ".aws", ".gnupg", ".npmrc", ".pypirc", ".netrc",
                 "credentials", "id_rsa", "id_ed25519") for p in lowered):
        raise ValueError("sensitive_workspace_path")
    if any((p == ".env" or p.startswith(".env.")) and p not in
           (".env.example", ".env.sample", ".env.template") for p in lowered):
        raise ValueError("sensitive_workspace_path")
    if lowered[-1].endswith((".pem", ".p12", ".pfx", ".key")):
        raise ValueError("sensitive_workspace_path")
    return path


def validate_workspace(files: Mapping[str, bytes]) -> dict[str, bytes]:
    if len(files) > MAX_FILES:
        raise ValueError("workspace_file_limit")
    result: dict[str, bytes] = {}
    canonical: set[str] = set()
    total = 0
    for path, data in files.items():
        validate_path(path)
        if not isinstance(data, bytes) or len(data) > MAX_FILE_BYTES:
            raise ValueError("workspace_file_limit")
        key = path.casefold()
        if key in canonical:
            raise ValueError("workspace_path_collision")
        canonical.add(key)
        total += len(data)
        if total > MAX_WORKSPACE_BYTES:
            raise ValueError("workspace_byte_limit")
        result[path] = data
    # A file cannot also be a parent directory, including case aliases.
    for path in canonical:
        if any(str(parent) in canonical for parent in PurePosixPath(path).parents if str(parent) != "."):
            raise ValueError("workspace_path_collision")
    return dict(sorted(result.items()))


def workspace_revision(files: Mapping[str, bytes]) -> str:
    digest = hashlib.sha256(b"agentforge-workspace-v1\0")
    for path, data in validate_workspace(files).items():
        name = path.encode("utf-8")
        digest.update(len(name).to_bytes(4, "big"))
        digest.update(name)
        digest.update(len(data).to_bytes(8, "big"))
        digest.update(data)
    return digest.hexdigest()


def read_text(files: Mapping[str, bytes], path: str) -> str:
    validate_path(path)
    data = files[path]
    if b"\0" in data:
        raise ValueError("binary_file_not_editable")
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise ValueError("binary_file_not_editable") from None


def write_text(files: Mapping[str, bytes], path: str, content: str,
               expected_sha256: str | None) -> dict[str, bytes]:
    """None means create-only; existing files always require an exact CAS hash."""
    result = validate_workspace(files)
    validate_path(path)
    if path in result:
        read_text(result, path)
        if expected_sha256 != hashlib.sha256(result[path]).hexdigest():
            raise ValueError("workspace_write_conflict")
    elif expected_sha256 is not None:
        raise ValueError("workspace_write_conflict")
    if "\0" in content:
        raise ValueError("binary_file_not_editable")
    result[path] = content.encode("utf-8")
    return validate_workspace(result)


def import_archive(archive: bytes) -> dict[str, bytes]:
    """Read bounded tar bytes without extracting to a host filesystem."""
    if len(archive) > MAX_ARCHIVE_BYTES:
        raise ValueError("archive_byte_limit")
    # Bound expansion before tarfile parses PAX/GNU extension headers. Otherwise
    # a compressed huge header may allocate memory before yielding a member.
    if archive.startswith(b"\x1f\x8b"):
        try:
            with gzip.GzipFile(fileobj=io.BytesIO(archive)) as compressed:
                archive = compressed.read(MAX_ARCHIVE_BYTES + 1)
        except (OSError, EOFError):
            raise ValueError("invalid_archive") from None
        if len(archive) > MAX_ARCHIVE_BYTES:
            raise ValueError("archive_expansion_limit")
    elif archive.startswith((b"BZh", b"\xfd7zXZ")):
        raise ValueError("unsupported_archive_compression")
    files: dict[str, bytes] = {}
    seen: set[str] = set()
    total = 0
    try:
        with tarfile.open(fileobj=io.BytesIO(archive), mode="r|") as tar:
            count = 0
            for member in tar:
                count += 1
                if count > MAX_FILES * 2:
                    raise ValueError("archive_entry_limit")
                name = member.name.rstrip("/") if member.isdir() else member.name
                validate_path(name)
                if name.casefold() in seen:
                    raise ValueError("archive_duplicate_path")
                seen.add(name.casefold())
                if member.isdir():
                    continue
                if not member.isfile() or member.issparse():
                    raise ValueError("archive_special_file")
                if member.size > MAX_FILE_BYTES or len(files) >= MAX_FILES:
                    raise ValueError("workspace_file_limit")
                total += member.size
                if total > MAX_WORKSPACE_BYTES:
                    raise ValueError("workspace_byte_limit")
                stream = tar.extractfile(member)
                if stream is None:
                    raise ValueError("invalid_archive")
                data = stream.read(MAX_FILE_BYTES + 1)
                if len(data) != member.size:
                    raise ValueError("invalid_archive")
                files[name] = data
    except (tarfile.TarError, EOFError, OSError):
        raise ValueError("invalid_archive") from None
    return validate_workspace(files)


def build_diff(baseline: Mapping[str, bytes], files: Mapping[str, bytes]) -> str:
    """Compare externally retained bytes; untrusted .git never defines the baseline."""
    before, after = validate_workspace(baseline), validate_workspace(files)
    chunks: list[str] = []
    size = 0
    for path in sorted(before.keys() | after.keys()):
        if before.get(path) == after.get(path):
            continue
        if (path not in before and after[path] == b"") or (path not in after and before[path] == b""):
            # Unified text hunks cannot represent an empty file's existence.
            # Git mode/index metadata can, including an empty-file deletion.
            chunk = f"diff --git {json.dumps('a/' + path)} {json.dumps('b/' + path)}\n"
            chunk += ("new file mode 100644\nindex 0000000..e69de29\n" if path not in before
                      else "deleted file mode 100644\nindex e69de29..0000000\n")
            chunks.append(chunk)
            continue
        try:
            old = read_text(before, path) if path in before else ""
            new = read_text(after, path) if path in after else ""
            lines = difflib.unified_diff(old.splitlines(keepends=True), new.splitlines(keepends=True),
                fromfile=f"a/{path}" if path in before else "/dev/null",
                tofile=f"b/{path}" if path in after else "/dev/null")
            chunk = "".join(line if line.endswith("\n") else line + "\n\\ No newline at end of file\n"
                            for line in lines)
        except ValueError:
            chunk = f"Binary files a/{path} and b/{path} differ\n"
        size += len(chunk.encode())
        if size > MAX_WORKSPACE_BYTES * 3:
            raise ValueError("diff_byte_limit")
        chunks.append(chunk)
    return "".join(chunks)

