111	  return <p className="mt-1 flex items-center gap-1.5 text-[13px] font-medium text-muted-foreground" data-activity-entry="phase" data-state={entry.state}>
112	    <span>{entry.label}</span>
113	    {entry.state === "failed" ? <><TriangleAlert className="size-3" aria-hidden="true" /><span className="font-normal">didn&apos;t finish</span></> : null}
114	  </p>;
115	});
116	
117	const NoteBlock = memo(function NoteBlock({ text }: { text: string }) {
118	  return <div className="min-w-0" data-activity-entry="note"><AssistantMessage content={text} /></div>;
119	});
120	
121	/**
122	 * A line about the connection or the run itself (stopping, thinking): the same row shape as a step. It plays the entrance only
123	 * when it is genuinely new: "Thinking" moves from the just-sent indicator into the run's own view as a fresh element, and
124	 * replaying the fade there would flicker.
125	 */
126	function StatusRow({ icon = "running", current, label, children, animate = false, fade = false }: { icon?: StatusIcon; current: boolean; label: string; children?: ReactNode; animate?: boolean; fade?: boolean }) {
127	  // Work in progress ("Thinking", "Stopping") is the shimmering words alone; only a warning keeps a glyph to mark it apart.
128	  // `fade`: a line that comes back during a run fades in slowly, so one that the run's end removes a moment later never flashes.
129	  return <li className={`${animate ? "message-in " : fade ? "status-fade " : ""}flex min-w-0 items-center gap-2.5`} data-activity-entry="status">
130	    {icon === "running" ? null : <Glyph icon={icon} tone="neutral" current={current} />}
131	    <span className="min-w-0 truncate">{current && icon === "running" ? <span className="thinking-shimmer">{label}</span> : label}</span>
132	    {children}
133	  </li>;
134	}
135	
136	// ---------------------------------------------------------------------------------------------------------------------
137	// Timeline
138	
139	type TimelineProps = {
140	  /** The task the entries belong to: disclosure choices are remembered per task. */
141	  taskId?: string;
142	  entries: readonly ActivityEntry[];
143	  /** The run is still going: a status line ("Thinking") may show. */
144	  live?: boolean;
145	  /** Nothing new has shown for a while. */
146	  quiet?: boolean;
147	  fallback?: string;
148	  /** Text still being written (a progress note, then the answer). */
149	  tail?: ReactNode;
150	  /** Trouble reaching the server, shown inside the timeline. */
151	  notice?: TimelineNotice | null;
152	  onRetry?: () => void;
153	  stopping?: boolean;
154	  /** Rows play their entrance. Off for activity that is loaded or was already shown, so nothing replays. */
155	  animate?: boolean;
156	  /** The one short sentence a screen reader hears (never the streamed words). Omitted: no status region. */
157	  announcement?: string;
158	  /** The run is over: its steps fold into the closed "Worked · 41s · N steps" disclosure, the same one the saved answer shows. */
159	  fold?: boolean;
160	  durationMs?: number | null;
161	  /** Calls the agent stopped before, waiting for an Approve / Decline. */
162	  approvals?: readonly PendingApproval[];
163	  /** The "Thinking" line plays its entrance (only the indicator shown the moment a message is sent). */
164	  statusEnters?: boolean;
165	  /** The tool call the live row shows: being written by the model, or running and printing. */
166	  liveTool?: LiveToolView | null;
167	};
168	
169	function renderSection(section: Section, taskId: string, current: string | null, animate: boolean, extra: ReactNode, outputFor: { entryId: string; text: string } | null, waiting: ReadonlySet<string>) {
170	  switch (section.kind) {
171	    case "note": return <NoteBlock key={section.id} text={section.entry.text} />;
172	    case "phase": return <PhaseHeading key={section.id} entry={section.entry} />;
173	    case "rows": return <ul key={section.id} className="space-y-2 text-[15px] leading-6 text-muted-foreground" aria-label="Steps">
174	      {chunkRows(section.entries).map((chunk) => chunk.kind === "subagents"
175	        ? <SubagentFleet key={chunk.key} taskId={taskId} calls={chunk.calls} animate={animate} waiting={waiting} />
176	        : <EntryRow key={chunk.key} taskId={taskId} entry={chunk.entry} current={chunk.entry.id === current} animate={animate} output={outputFor?.entryId === chunk.entry.id ? outputFor.text : undefined} />)}
177	      {extra}
178	    </ul>;
179	  }
180	}
181	
182	/**
183	 * What the agent said and did, oldest first, as it happened: its notes in the person's own reading voice and one line per step.
184	 * While `live`, one status line ("Thinking") appears only when nothing else shows that work is going on: no step is running and
185	 * no text is being written (`tail`). Straight after the start of a run that is immediately; once there is something to read,
186	 * only when the run has been `quiet` for a while, so it never competes with text the agent has just written.
187	 *
188	 * The log itself is `aria-live="off"`: streaming text and growing rows would be read out word by word. A separate polite status
189	 * says only what changed in the run (`announcement`).
190	 */
191	export function Timeline({ taskId = "", entries, live = false, quiet = false, fallback = "Thinking", tail, notice = null, onRetry, stopping = false, animate = true, announcement, fold = false, durationMs, approvals = [], statusEnters = false, liveTool = null }: TimelineProps) {
192	  const sections = useMemo(() => sectionsOf(entries), [entries]);
193	  const callId = useMemo(() => currentCallId(entries), [entries]);
194	  // Subagents that have a question for the person, and whose each question is.
195	  const subagents = useMemo(() => subagentsByRun(entries), [entries]);
196	  const waiting = useMemo(() => new Set(approvals.flatMap((approval) => approval.agentRunId ? [approval.agentRunId] : [])), [approvals]);
197	  const nothingYet = !entries.some((entry) => entry.kind !== "phase");
198	  // A call being written, or a running command's output. Not shown once the run is folded away into its summary.
199	  const placement = useMemo(() => fold ? null : placeLiveTool(entries, liveTool, approvals.length > 0), [fold, entries, liveTool, approvals.length]);
200	  const draftRow = placement?.kind === "draft" ? <DraftRow key={`draft:${placement.call.callId}`} call={placement.call} /> : null;
201	  const outputFor = placement?.kind === "output" ? placement : null;
202	  // A call being written is work in progress too: "Thinking" would say nothing is happening while its text is arriving.
203	  const running = callId !== null || stopping || !!draftRow;
204	  // A connection notice stands in for "Thinking" when nothing else shows life; otherwise it sits quietly under the rest.
205	  // A waiting approval card is the sign of life: "Thinking" would say the agent is busy while it waits for the person.
206	  const status = live && !tail && !running && !notice && !approvals.length && (nothingYet || quiet);
207	  const noticeLeads = !!notice && !tail && !running && notice.kind !== "halted" && notice.kind !== "failed";
208	  const current = stopping ? "stopping" : callId;
209	  const last = sections[sections.length - 1];
210	  const stoppingRow = stopping ? <StatusRow key="stopping" current label="Stopping" animate /> : null;
211	  // What follows the last list of steps: the call being written, then "Stopping". Each opens a list of its own after a note or heading.
212	  const trailing = draftRow || stoppingRow ? <>{draftRow}{stoppingRow}</> : null;
213	  return <>
214	    <div className="flex min-w-0 flex-col gap-3" role="log" aria-live="off" aria-label="Agent activity" data-activity-log data-live={live ? "true" : undefined}>
215	      {fold ? <ActivityDisclosure taskId={taskId} entries={entries} durationMs={durationMs} className="" />
216	        : sections.map((section, index) => renderSection(section, taskId, current, animate, section.kind === "rows" && index === sections.length - 1 ? trailing : null, outputFor, waiting))}
217	      {trailing && last?.kind !== "rows" ? <ul className="space-y-2 text-[15px] leading-6 text-muted-foreground" aria-label="Steps">{trailing}</ul> : null}
218	      {approvals.map((approval) => <ApprovalCard key={approval.id} approval={approval} source={approvalSource(approval.agentRunId, subagents)} />)}
219	      {tail}
220	      {notice ? <ul className="text-[15px] leading-6 text-muted-foreground" aria-label="Connection" data-activity-notice={notice.kind}>
221	        <StatusRow icon={noticeLeads ? "running" : notice.kind === "reconnecting" || notice.kind === "catching_up" ? "unknown" : "warning"} current={noticeLeads} label={notice.text} animate>
222	          {notice.kind === "failed" && onRetry ? <button type="button" onClick={onRetry} className={`ml-1 shrink-0 rounded px-1 font-medium text-foreground underline underline-offset-4 [@media(pointer:coarse)]:min-h-11 ${toggleClass}`}>Retry</button> : null}
223	        </StatusRow>
224	      </ul> : null}
225	      {status ? <ul className="text-[15px] leading-6 text-muted-foreground" aria-label="Status"><StatusRow current label={fallback} animate={statusEnters} fade={!statusEnters && !nothingYet} /></ul> : null}
226	    </div>
227	    {announcement !== undefined ? <span role="status" aria-live="polite" className="sr-only" data-activity-status>{announcement}</span> : null}
228	  </>;
229	}
230	
231	// ---------------------------------------------------------------------------------------------------------------------
232	// Disclosure of a finished run's activity
233	
234	/** Entries read from the server for finished replies, kept for the page session so reopening is instant and costs no request. */
235	const history = new Map<string, readonly ActivityEntry[]>();
236	const HISTORY_LIMIT = 40;
237	
238	function useHistoryEntries(taskId: string, terminal: boolean, enabled: boolean) {
239	  const [attempt, setAttempt] = useState(0);
240	  const [result, setResult] = useState<{ key: string; entries?: readonly ActivityEntry[]; error?: string } | null>(null);
241	  const key = `${taskId}:${attempt}`;
242	  const cached = history.get(taskId);
243	  useEffect(() => {
244	    if (!enabled || cached) return;
245	    const controller = new AbortController();
246	    loadHistoryEntries(taskId, { terminal }, (after, limit, signal) => fetchEventHistory(taskId, after, limit, { signal }), controller.signal).then(
247	      (entries) => {
248	        history.set(taskId, entries);
249	        while (history.size > HISTORY_LIMIT) history.delete(history.keys().next().value as string);
250	        if (!controller.signal.aborted) setResult({ key, entries });
251	      },
252	      () => { if (!controller.signal.aborted) setResult({ key, error: "Couldn’t load this reply’s activity." }); },
253	    );
254	    return () => controller.abort();
255	  }, [enabled, cached, taskId, terminal, key]);
256	  const entries = cached ?? (result?.key === key ? result.entries : undefined);
257	  const error = entries ? undefined : result?.key === key ? result.error : undefined;
258	  return { entries, error, loading: enabled && !entries && !error, retry: () => setAttempt((value) => value + 1) };
259	}
260	
261	/**
262	 * Collapsible summary of a run's work. Given `entries` (a run that just ended in this view) it shows them, closed unless the person opened it.
263	 * Given only a `taskId` and the message's `activity` (history) it is collapsed, labelled from the exact action count, and loads
264	 * the whole timeline the first time it opens. Without `activity` (an older server) `legacyCount` stands in for the count.
265	 */
266	export function ActivityDisclosure({ taskId, activity, entries, durationMs, legacyCount = 0, className = "mb-3" }: {
267	  taskId: string;
268	  activity?: MessageActivity | null;
269	  entries?: readonly ActivityEntry[];
270	  /** How long the run took, when known; history reads it from `activity.duration_ms` instead. */
271	  durationMs?: number | null;
272	  legacyCount?: number;
273	  className?: string;
274	}) {
275	  const [open, toggle] = useDisclosure(disclosureKey(taskId, ACTIVITY_DISCLOSURE), false);
276	  const panelId = useId();
277	  const counts = useMemo(() => entries ? summarizeEntries(entries) : null, [entries]);
278	  const actions = counts ? counts.actions : activity ? activity.action_count : legacyCount;
279	  const notes = counts ? counts.notes : activity?.note_count ?? 0;
280	  const available = counts ? actions > 0 || notes > 0 : activity ? activity.available : legacyCount > 0;
281	  const loaded = useHistoryEntries(taskId, activity?.terminal ?? true, open && available && !entries);
282	  if (!available) return null;
283	  const shown = entries ?? loaded.entries;
284	  return <div className={className} data-activity-disclosure>
285	    <button type="button" aria-expanded={open} aria-controls={panelId} data-scroll-anchor-toggle className={`-ml-1 inline-flex min-h-8 items-center gap-1 rounded-lg px-1 text-[13px] text-muted-foreground [@media(pointer:coarse)]:min-h-11 ${toggleClass}`} onClick={toggle}>
286	      {chevron(open)}
287	      {activityLabel(actions, durationMs ?? activity?.duration_ms)}
288	    </button>
289	    <div id={panelId} hidden={!open} className="mt-1.5 ml-1.5 border-l pl-4 text-sm">
290	      {open ? (loaded.error ? <p role="alert" className="text-muted-foreground">{loaded.error} <button type="button" onClick={loaded.retry} className={`rounded px-1 font-medium text-foreground underline underline-offset-4 [@media(pointer:coarse)]:min-h-11 ${toggleClass}`}>Retry</button></p>
291	        : shown ? (shown.length ? <Timeline taskId={taskId} entries={shown} animate={false} /> : <p className="text-muted-foreground">No recorded activity.</p>)
292	          : <p role="status" className="text-muted-foreground">Loading…</p>) : null}
293	    </div>
294	  </div>;
295	}
